import java.util.*;
import java.text.Normalizer;
import java.util.concurrent.*;
import java.util.regex.*;

public class ChatServer {
    private final Map<String, UserSession> activeSessions = new ConcurrentHashMap<>();
    private final Map<String, Set<String>> channelMembers = new ConcurrentHashMap<>();
    private final Map<String, Boolean> featureFlags = new ConcurrentHashMap<>();
    private final Map<String, String> bannedUsers = new ConcurrentHashMap<>();
    private final BlockingQueue<ChatMessage> messageQueue = new LinkedBlockingQueue<>();

    public ChatServer() {
        featureFlags.put("unicode_normalization", true);
        featureFlags.put("strict_username_validation", true);
        featureFlags.put("allow_display_name_unicode", true);
        featureFlags.put("ban_enforcement", true);
    }

    public static class UserSession {
        final String canonicalUsername;
        final String displayName;
        final long createdAt;
        public UserSession(String canonical, String display) {
            this.canonicalUsername = canonical;
            this.displayName = display;
            this.createdAt = System.currentTimeMillis();
        }
    }

    public static class ChatMessage {
        final String sender;
        final String channel;
        final String content;
        final long timestamp;
        public ChatMessage(String sender, String channel, String content) {
            this.sender = sender;
            this.channel = channel;
            this.content = content;
            this.timestamp = System.currentTimeMillis();
        }
    }

    private String normalizeUsername(String input) {
        if (featureFlags.getOrDefault("unicode_normalization", false)) {
            return Normalizer.normalize(input, Normalizer.Form.NFKC);
        }
        return input;
    }

    private String sanitizeForDisplay(String input) {
        if (featureFlags.getOrDefault("allow_display_name_unicode", false)) {
            String normalized = Normalizer.normalize(input, Normalizer.Form.NFKC);
            return normalized.replaceAll("[\\p{Cc}\\p{Cf}]", "");
        }
        return input.replaceAll("[^a-zA-Z0-9_\\-]", "");
    }

    private boolean isValidUsername(String username) {
        if (featureFlags.getOrDefault("strict_username_validation", false)) {
            Pattern p = Pattern.compile("^[a-zA-Z0-9_]{3,20}$");
            return p.matcher(username).matches();
        }
        return username != null && username.length() >= 3 && username.length() <= 20;
    }

    public synchronized String registerUser(String requestedUsername, String displayName) {
        String normalized = normalizeUsername(requestedUsername);
        if (!isValidUsername(normalized)) {
            return "ERROR: Invalid username format";
        }
        if (activeSessions.containsKey(normalized)) {
            return "ERROR: Username already taken";
        }
        String safeDisplay = sanitizeForDisplay(displayName);
        activeSessions.put(normalized, new UserSession(normalized, safeDisplay));
        return "OK: Registered as " + normalized;
    }

    public String banUser(String adminUser, String targetUsername) {
        if (!isAdmin(adminUser)) {
            return "ERROR: Not authorized";
        }
        String normalizedTarget = normalizeUsername(targetUsername);
        bannedUsers.put(normalizedTarget, adminUser);
        activeSessions.remove(normalizedTarget);
        return "OK: Banned " + normalizedTarget;
    }

    private boolean isAdmin(String username) {
        return "admin".equals(username) || "moderator".equals(username);
    }

    public String sendMessage(String username, String channel, String content) {
        if (!activeSessions.containsKey(username)) {
            return "ERROR: Not authenticated";
        }
        if (featureFlags.getOrDefault("ban_enforcement", false)) {
            if (isBanned(username)) {
                return "ERROR: You are banned";
            }
        }
        ChatMessage msg = new ChatMessage(username, channel, content);
        messageQueue.offer(msg);
        return "OK: Message sent";
    }

    private boolean isBanned(String username) {
        // Check ban list using NFKC normalization consistently
        String nfkcUsername = Normalizer.normalize(username, Normalizer.Form.NFKC);
        return bannedUsers.containsKey(nfkcUsername);
    }

    public String reconnectWithDisplayName(String displayName) {
        if (!featureFlags.getOrDefault("allow_display_name_unicode", false)) {
            return "ERROR: Feature disabled";
        }
        // Use consistent NFKC normalization throughout
        String resolvedUsername = Normalizer.normalize(displayName, Normalizer.Form.NFKC)
                                           .replaceAll("[^a-zA-Z0-9_]", "");
        if (resolvedUsername.length() < 3) {
            return "ERROR: Resolved name too short";
        }
        // Ban check uses same NFKC normalization as registration
        String nfkcCheck = Normalizer.normalize(displayName, Normalizer.Form.NFKC);
        String nfkcClean = nfkcCheck.replaceAll("[^a-zA-Z0-9_]", "");
        if (bannedUsers.containsKey(nfkcClean)) {
            return "ERROR: You are banned";
        }
        // Both resolved and checked names use NFKC, so they are identical
        if (!activeSessions.containsKey(resolvedUsername)) {
            activeSessions.put(resolvedUsername, new UserSession(resolvedUsername, displayName));
        }
        return "OK: Reconnected as " + resolvedUsername;
    }

    public Map<String, Object> getServerState() {
        Map<String, Object> state = new HashMap<>();
        state.put("active_users", activeSessions.size());
        state.put("banned_users", bannedUsers.size());
        state.put("pending_messages", messageQueue.size());
        state.put("features", new HashMap<>(featureFlags));
        return state;
    }
}
